{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values to compute the net stage 1 action values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a perseveration bonus to the stage 1 value of the action chosen in the previous trial.",
      "params": [
        {
          "name": "pers",
          "bounds": [0, 1]
        }
      ],
      "evidence": "if last_action != -1:\n            pers_bonus = np.zeros(2)\n            pers_bonus[last_action] = pers\n            q_stage1_net += pers_bonus",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage 1 model-free value using the stage 2 reward prediction error, scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "separate_stage2_temperature",
      "title": "Separate Stage-2 Inverse Temperature",
      "description": "Uses a distinct inverse temperature parameter for stage 2 choices, allowing different levels of choice stochasticity across stages.",
      "params": [
        {
          "name": "beta2",
          "bounds": [0, 10]
        }
      ],
      "evidence": "exp_q2 = np.exp(beta2 * (q_stage2_mf[state_idx] - np.max(q_stage2_mf[state_idx])))",
      "expressible_in_slots": true
    }
  ]
}
